```matlab
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% H2 State Feedback Controller Design using LMI Formulation
% 
% This MATLAB code designs an H2 state feedback controller that minimizes
% the sum of squared H2 norms of transfer functions from input disturbance
% to output and to control input.
%
% The optimization problem is formulated using the Schur complement lemma
% and bounded real lemma to handle the nonlinearity in the system structure.
%
% System: Active Suspension System
% Objective: Minimize ||T_wz||_2^2 + ||T_wu||_2^2
% Where: T_wz = transfer from disturbance to output (Cx)
%        T_wu = transfer from disturbance to control input (-Kx)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

clc
clear all
close all

%% Load and prepare system data
% Load system identification data
load('data3.mat');

% Identify system using Box-Jenkins model
G3 = bj(data3, [5, 5, 5, 5, 1]);

% Convert discrete-time model to continuous-time
G3_c = d2c(G3);

% Extract state-space matrices
[A, B, C, D] = ssdata(G3_c);

% System dimensions
n = size(A, 1);  % Number of states
m = size(B, 2);  % Number of inputs
p = size(C, 1);  % Number of outputs

%% H2 State Feedback Controller Design using LMI Formulation
% Define decision variables for YALMIP
X = sdpvar(n, n, 'symmetric');  % Lyapunov matrix
Y = sdpvar(m, n, 'full');       % Y = K*X
Z1 = sdpvar(p, p, 'symmetric'); % For output term
Z2 = sdpvar(m, m, 'symmetric'); % For control term

% Define epsilon for strict inequalities (numerical robustness)
epsilon = 1e-6;

% LMI 1: Stability condition (Bounded Real Lemma formulation)
% A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*I
LMI1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*eye(n)];

% LMI 2: Positive definiteness of X
% X >= epsilon*I
LMI2 = [X >= epsilon*eye(n)];

% LMI 3: Schur complement for output term
% [Z1, C*X; X*C', X] >= 0
LMI3 = [[Z1, C*X; X*C', X] >= 0];

% LMI 4: Schur complement for control term
% [Z2, Y; Y', X] >= 0
LMI4 = [[Z2, Y; Y', X] >= 0];

% Combine all LMIs
LMIs = [LMI1, LMI2, LMI3, LMI4];

% Objective function: Minimize trace(Z1) + trace(Z2)
Objective = trace(Z1) + trace(Z2);

% Solver settings
options = sdpsettings('solver', 'sedumi', 'verbose', 1);

% Solve the LMI optimization problem
diagnostics = optimize(LMIs, Objective, options);

% Check if solution was found
if diagnostics.problem == 0
    disp('Optimization successfully solved!');
else
    error(['Optimization failed: ', diagnostics.info]);
end

%% Extract solution and compute controller gain
% Get optimal values
X_opt = value(X);
Y_opt = value(Y);
Z1_opt = value(Z1);
Z2_opt = value(Z2);

% Compute controller gain: K = Y * X^(-1)
K = Y_opt / X_opt;

%% Compute H2 norms and validate performance
A_cl = A - B*K;
sys_cl = ss(A_cl, B, C, D);

% Step response comparison with LQR
figure;
step(sys_cl);
hold on;

% Design LQR controller for comparison
Q_lqr = C'*C + 1e-3*eye(n);
R_lqr = eye(m);
[K_lqr, ~, ~] = lqr(A, B, Q_lqr, R_lqr);
sys_cl_lqr = ss(A-B*K_lqr, B, C, D);
step(sys_cl_lqr);
legend('H2 Controller', 'LQR Controller');
grid on;

title('Step Response Comparison: H2 vs LQR');
xlabel('Time (s)');
ylabel('Amplitude');

%% Display performance metrics
fprintf('H2 Controller Performance:\n');
fprintf('------------------------\n');
fprintf('Achieved H2 norm: %.4f\n', sqrt(trace(C*X_opt*C') + trace(K*X_opt*K')));
fprintf('Trace bounds: %.4f (actual) vs %.4f (optimization)\n', 
       trace(C*X_opt*C') + trace(K*X_opt*K'), trace(Z1_opt) + trace(Z2_opt));
```

