```dart
import 'dart:io';

/// Slices an image into four equal parts from the center using byte data
/// 
/// Parameters:
/// - `imageBytes`: The image bytes to slice
/// 
/// Returns:
/// - List<Uint8List> containing the four sliced parts in order:
///   [top-left, top-right, bottom-left, bottom-right]
Future<List<Uint8List>> sliceImageIntoFourBytes(Uint8List imageBytes) async {
  // Decode the image
  final codec = await instantiateImageCodec(imageBytes);
  final frame = await codec.getNextFrame();
  final image = frame.image;

  // Get original image dimensions
  final width = image.width;
  final height = image.height;

  // Calculate center point
  final centerX = width ~/ 2;
  final centerY = height ~/ 2;

  // Define the four quadrants
  final quadrants = [
    // Top-left quadrant
    Rect.fromLTWH(0, 0, centerX.toDouble(), centerY.toDouble()),
    // Top-right quadrant
    Rect.fromLTWH(centerX.toDouble(), 0, (width - centerX).toDouble(), centerY.toDouble()),
    // Bottom-left quadrant
    Rect.fromLTWH(0, centerY.toDouble(), centerX.toDouble(), (height - centerY).toDouble()),
    // Bottom-right quadrant
    Rect.fromLTWH(centerX.toDouble(), centerY.toDouble(), 
                  (width - centerX).toDouble(), (height - centerY).toDouble()),
  ];

  // Convert each quadrant to bytes
  final result = <Uint8List>[];

  for (final quadrant in quadrants) {
    // Extract the quadrant
    final recorder = PictureRecorder();
    final canvas = Canvas(recorder);

    canvas.drawImageRect(
      image,
      quadrant,  // Source rectangle
      Rect.fromLTWH(0, 0, quadrant.width, quadrant.height),  // Destination rectangle
      Paint(),
    );

    // Convert to image
    final picture = recorder.endRecording();
    final img = await picture.toImage(
      quadrant.width.toInt(),
      quadrant.height.toInt(),
    );

    // Convert to bytes
    final byteData = await img.toByteData();
    result.add(byteData!.buffer.asUint8List());
  }

  return result;
}
