            int fx = sbox[x];
            outputBits[x][0] = (fx >> 2) & 1;
            outputBits[x][1] = (fx >> 1) & 1;
            outputBits[x][2] = fx & 1;
        }

        // Compute LAT for all input masks a (0-7) and output masks b (0-7)
        for (int a = 0; a < 8; a++) {
            // Binary representation of input mask a
            int a0 = (a >> 2) & 1;
            int a1 = (a >> 1) & 1;
            int a2 = a & 1;

            for (int b = 0; b < 8; b++) {
                // Binary representation of output mask b
                int b0 = (b >> 2) & 1;
                int b1 = (b >> 1) & 1;
                int b2 = b & 1;

                int count = 0;

                // For all inputs x (0-7)
                for (int x = 0; x < 8; x++) {
                    // Compute a·x = Σ (a_i & x_i) mod 2
                    int aDotX = (a0 & inputBits[x][0]) ^ (a1 & inputBits[x][1]) ^ (a2 & inputBits[x][2]);

                    // Compute b·S(x) = Σ (b_i & S(x)_i) mod 2
                    int bDotFx = (b0 & outputBits[x][0]) ^ (b1 & outputBits[x][1]) ^ (b2 & outputBits[x][2]);

                    // Check if a·x = b·S(x)
                    if (aDotX == bDotFx) {
                        count++;
                    }
                }

                // Normalize by subtracting 4 (expected value for random function)
                lat[a][b] = count - 4;
            }
        }

        return lat;
    }

