#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

typedef long long ll;
const ll INF = 1e18;

vector<ll> dijkstra(int n, const vector<vector<pair<int, int>>>& adj, int start) {
    vector<ll> dist(n + 1, INF);
    dist[start] = 0;
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            ll newDist = d + w;
            if (newDist < dist[v]) {
                dist[v] = newDist;
                pq.push({newDist, v});
            }
        }
    }
    return dist;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<pair<int, int>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    vector<ll> dist1 = dijkstra(n, adj, 1);
    vector<ll> distN = dijkstra(n, adj, n);

    vector<pair<ll, ll>> nodes;
    for (int i = 1; i <= n; i++) {
        nodes.push_back({dist1[i], distN[i]});
    }
    sort(nodes.begin(), nodes.end());

    vector<ll> prefix_min(n);
    prefix_min[0] = nodes[0].second;
    for (int i = 1; i < n; i++) {
        prefix_min[i] = min(prefix_min[i-1], nodes[i].second);
    }

    for (int day = 0; day < k; day++) {
        ll a, b;
        cin >> a >> b;

        ll lo = 0, hi = INF;
        while (lo < hi) {
            ll mid = lo + (hi - lo) / 2;
            bool possible = false;

            ll max_d1 = (a > 0) ? mid / a : INF;
            auto it = upper_bound(nodes.begin(), nodes.end(), make_pair(max_d1, INF));
            int pos = it - nodes.begin();

            if (pos > 0) {
                ll max_d2 = (b > 0) ? mid / b : INF;
                if (prefix_min[pos-1] <= max_d2) {
                    possible = true;
                }
            }

            if (possible) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        cout << lo << "\n";
    }

    return 0;
}
