## Why `execute(Params...)` is Deprecated in Android 11.0 (API 30+)

The `AsyncTask.execute(Params...)` method was deprecated in Android API 30 (Android 11) for several important reasons:

1. **Memory Leaks**: AsyncTask had inherent memory leak issues, especially when tasks continued running after activities/fragments were destroyed.
2. **Poor Thread Management**: Used a static thread pool with no customization, leading to unpredictable behavior.
3. **Lack of Lifecycle Awareness**: Tasks continued running after UI components were destroyed.
4. **Modern Alternatives**: Better solutions like `ExecutorService` and Coroutines are now available.
5. **Performance Issues**: Didn't scale well for modern app requirements.

## Modern Alternatives with Backward Compatibility

### 1. ExecutorService (Recommended for API 11+)
```java
ExecutorService executor = Executors.newSingleThreadExecutor();
executor.execute(() -> {
    // Network operation here
    runOnUiThread(() -> {
        // Update UI
    });
});
```

### 2. Kotlin Coroutines (Recommended for Modern Android)
```kotlin
lifecycleScope.launch {
    val result = withContext(Dispatchers.IO) {
        // Network operation
    }
    // Update UI with result
}
```

### Backward Compatibility Solution
```java
if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.HONEYCOMB) {
    // Use ExecutorService for API 11+
    ExecutorService executor = Executors.newSingleThreadExecutor();
    executor.execute(/*...*/);
} else {
    // Fallback to AsyncTask for pre-Honeycomb
    new LegacyAsyncTask().execute();
}
```

The modern alternatives address the deprecation issues while maintaining backward compatibility with older Android versions.

```python
#!/usr/bin/env python3
import re
import sys
import csv
import os
import PyPDF2
import pandas as pd
from datetime import datetime
from pathlib import Path
from collections import defaultdict
from concurrent.futures import ProcessPoolExecutor, as_completed
import warnings
import traceback
from typing import List, Tuple, Optional, Dict, Any
import gc

# Suppress warnings for cleaner output
warnings.filterwarnings('ignore')

# Try to import tabula, but provide fallback if not available
try:
    import tabula
    TABULA_AVAILABLE = True
except ImportError:
    TABULA_AVAILABLE = False
    print("Warning: tabula-py not installed. Using PyPDF2 fallback for text extraction.")

class PDFProcessor:
    """Main class for processing PDFs with robust error handling and optimization"""

    def __init__(self, max_workers: int = None, chunk_size: int = 5000):
        # Auto-detect optimal worker count
        self.max_workers = max_workers or min(4, os.cpu_count() or 1)
        self.chunk_size = chunk_size
        self.processed_count = 0
        self.failed_count = 0
        self.total_pages = 0
        self._date_cache = {}  # Cache for date extraction

    def extract_date_from_pdf(self, file_path: str) -> datetime:
        """Extract date from PDF with caching for performance"""
        if file_path in self._date_cache:
            return self._date_cache[file_path]

        try:
            filename = os.path.basename(file_path)

            # Comprehensive date patterns
            date_patterns = [
                r'(\d{4}[-/]\d{2}[-/]\d{2})',  # YYYY-MM-DD or YYYY/MM/DD
                r'(\d{2}[-/]\d{2}[-/]\d{4})',  # DD-MM-YYYY or DD/MM/YYYY
                r'(\d{8})',  # YYYYMMDD
                r'(\d{4}-\d{2})',  # YYYY-MM (monthly statements)
                r'(\d{6})',  # YYMMDD or MMDDYY
                r'statement_(\d{4})(\d{2})',  # statement_YYYYMM
                r'(\d{2}[A-Za-z]{3}\d{4})',  # 01Jan2024
            ]

            for pattern in date_patterns:
                match = re.search(pattern, filename, re.IGNORECASE)
                if match:
                    date_str = match.group(1) if len(match.groups()) == 1 else f"{match.group(1)}{match.group(2)}01"

                    # Try different date formats
                    date_formats = [
                        '%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y', '%d/%m/%Y',
                        '%Y%m%d', '%Y-%m', '%y%m%d', '%m%d%y',
                        '%d%b%Y', '%d-%b-%Y'
                    ]

                    for fmt in date_formats:
                        try:
                            result = datetime.strptime(date_str, fmt)
                            self._date_cache[file_path] = result
                            return result
                        except ValueError:
                            continue

            # Try PDF metadata with validation
            try:
                with open(file_path, 'rb') as file:
                    pdf_reader = PyPDF2.PdfReader(file)

                    # Validate PDF structure
                    if len(pdf_reader.pages) == 0:
                        raise ValueError("PDF has no pages")

                    metadata = pdf_reader.metadata
                    if metadata and '/CreationDate' in metadata:
                        date_str = metadata['/CreationDate']
                        if date_str.startswith('D:'):
                            date_str = date_str[2:10]  # Extract YYYYMMDD
                            if len(date_str) == 8 and date_str.isdigit():
                                result = datetime.strptime(date_str, '%Y%m%d')
                                self._date_cache[file_path] = result
                                return result
            except Exception:
                pass  # Silently continue to next fallback

            # Use file modification time as fallback
            try:
                result = datetime.fromtimestamp(os.path.getmtime(file_path))
                self._date_cache[file_path] = result
                return result
            except:
                result = datetime.now()
                self._date_cache[file_path] = result
                return result

        except Exception:
            result = datetime.now()
            self._date_cache[file_path] = result
            return result

    def validate_pdf_structure(self, file_path: str) -> Tuple[bool, Optional[str], Optional[int]]:
        """Validate PDF structure and get page count safely"""
        try:
            # Check file exists and is readable
            if not os.path.exists(file_path):
                return False, "File does not exist", 0

            if not os.access(file_path, os.R_OK):
                return False, "File is not readable", 0

            with open(file_path, 'rb') as file:
                # Check file size
                file.seek(0, 2)  # Seek to end
                file_size = file.tell()
                file.seek(0)  # Reset to beginning

                if file_size == 0:
                    return False, "Empty PDF file", 0

                if file_size > 500 * 1024 * 1024:  # 500MB limit
                    return False, f"PDF too large ({file_size/1024/1024:.1f} MB)", 0

                # Try to read PDF
                try:
                    pdf_reader = PyPDF2.PdfReader(file)
                except PyPDF2.errors.PdfReadError as e:
                    return False, f"Invalid PDF format: {e}", 0

                # Check if PDF is encrypted
                if pdf_reader.is_encrypted:
                    try:
                        # Try to decrypt with empty password
                        pdf_reader.decrypt('')
                    except:
                        return False, "PDF is encrypted and cannot be decrypted", 0

                page_count = len(pdf_reader.pages)

                if page_count == 0:
                    return False, "PDF has no pages", 0

                # Quick validation of first page only for performance
                if page_count > 0:
                    try:
                        page = pdf_reader.pages[0]
                        _ = page.extract_text()  # Try to extract text
                    except Exception as e:
                        return False, f"Page 1 extraction failed: {e}", page_count

                return True, None, page_count

        except Exception as e:
            return False, f"PDF validation error: {e}", 0

    def extract_text_with_pypdf2(self, file_path: str, page_range: str) -> List[List[str]]:
        """Extract text from PDF using PyPDF2 with optimized parsing"""
        try:
            with open(file_path, 'rb') as file:
                pdf_reader = PyPDF2.PdfReader(file)
                total_pages = len(pdf_reader.pages)

                # Parse page range efficiently
                if '-' in page_range:
                    start_str, end_str = page_range.split('-')
                    try:
                        start = max(1, int(start_str))
                        end = min(total_pages, int(end_str))
                        if start > end:
                            start, end = end, start
                        pages_to_process = range(start-1, end)
                    except ValueError:
                        pages_to_process = range(min(10, total_pages))  # Process first 10 pages max
                else:
                    try:
                        page_num = int(page_range)
                        pages_to_process = [min(page_num, total_pages) - 1]
                    except ValueError:
                        pages_to_process = range(min(10, total_pages))  # Process first 10 pages max

                text_data = []
                for page_num in pages_to_process:
                    try:
                        if page_num >= total_pages:
                            break

                        page = pdf_reader.pages[page_num]
                        text = page.extract_text()

                        if text and text.strip():
                            # Optimized text parsing
                            lines = text.split('\n')
                            for line in lines:
                                line = line.strip()
                                if line:
                                    # Split by 2+ spaces or tabs
                                    columns = [col.strip() for col in re.split(r'\s{2,}|\t', line) if col.strip()]
                                    if columns:
                                        text_data.append(columns)
                    except Exception:
                        continue  # Skip problematic pages

                return text_data

        except Exception:
            return []

    def process_pdf_with_tabula(self, file_path: str, last_page: int) -> Optional[List[List[str]]]:
        """Process PDF using tabula with optimized settings"""
        if not TABULA_AVAILABLE:
            return None

        try:
            # Limit pages for performance
            pages_to_process = min(last_page, 20)  # Process max 20 pages

            # Optimized tabula configuration
            try:
                dfs = tabula.read_pdf(
                    file_path,
                    pages=f'1-{pages_to_process}',
                    multiple_tables=True,
                    stream=True,  # Faster for table extraction
                    guess=False,  # Disable guessing for speed
                    silent=True,
                    lattice=False,  # Disable lattice mode for speed
                    pandas_options={'dtype': str}  # Keep as strings
                )

                if dfs:
                    # Combine and clean data efficiently
                    all_data = []
                    for df in dfs:
                        if not df.empty:
                            # Convert to list of lists, handling NaN values
                            data = df.where(pd.notna(df), '').astype(str).values.tolist()
                            all_data.extend(data)

                    return all_data

            except Exception:
                # Try alternative configuration
                try:
                    dfs = tabula.read_pdf(
                        file_path,
                        pages='1',  # Just first page
                        multiple_tables=True,
                        stream=True,
                        silent=True
                    )

                    if dfs:
                        all_data = []
                        for df in dfs:
                            if not df.empty:
                                data = df.where(pd.notna(df), '').astype(str).values.tolist()
                                all_data.extend(data)

                        return all_data
                except Exception:
                    pass

            return None

        except Exception:
            return None

    def process_single_pdf(self, file_path: str) -> Tuple[List[List[str]], Optional[str], Dict[str, Any]]:
        """Process a single PDF with memory-efficient approach"""
        metadata = {
            'filename': os.path.basename(file_path),
            'success': False,
            'error': None,
            'pages_processed': 0,
            'rows_extracted': 0
        }

        try:
            # Validate PDF first
            is_valid, error_msg, page_count = self.validate_pdf_structure(file_path)

            if not is_valid:
                metadata['error'] = error_msg
                return [], None, metadata

            # Extract date
            pdf_date = self.extract_date_from_pdf(file_path)
            date_str = pdf_date.strftime('%Y-%m-%d')

            # Process PDF with memory-efficient approach
            data = []

            if TABULA_AVAILABLE:
                tabula_data = self.process_pdf_with_tabula(file_path, page_count)
                if tabula_data:
                    data = tabula_data
                else:
                    # Fallback to PyPDF2
                    data = self.extract_text_with_pypdf2(file_path, f'1-{min(page_count, 10)}')
            else:
                data = self.extract_text_with_pypdf2(file_path, f'1-{min(page_count, 10)}')

            # Process data in chunks to manage memory
            processed_data = []
            for row in data:
                if row and any(str(item).strip() for item in row):
                    # Clean row efficiently
                    cleaned_row = ['' if pd.isna(item) else str(item).strip() for item in row]
                    processed_data.append([date_str] + cleaned_row)

            # Update metadata
            metadata.update({
                'success': True,
                'pages_processed': page_count,
                'rows_extracted': len(processed_data)
            })

            # Force garbage collection
            del data
            gc.collect()

            return processed_data, date_str, metadata

        except Exception as e:
            metadata['error'] = f"Unexpected error: {str(e)}"
            return [], None, metadata

    def process_pdfs_parallel(self, pdf_files: List[Path]) -> Tuple[List[List[str]], Dict[str, str]]:
        """Process multiple PDFs in parallel with optimized resource usage"""
        all_data = []
        date_file_map = {}

        print(f"Processing {len(pdf_files)} PDFs with {self.max_workers} workers...")

        # Group files into batches for better memory management
        batch_size = max(10, len(pdf_files) // (self.max_workers * 2))
        file_batches = [pdf_files[i:i + batch_size] for i in range(0, len(pdf_files), batch_size)]

        for batch_idx, file_batch in enumerate(file_batches, 1):
            print(f"Processing batch {batch_idx}/{len(file_batches)} ({len(file_batch)} files)...")

            # Use ProcessPoolExecutor for CPU-bound tasks
            with ProcessPoolExecutor(max_workers=self.max_workers) as executor:
                # Submit tasks for current batch
                future_to_file = {
                    executor.submit(self.process_single_pdf, str(pdf_file)): pdf_file 
                    for pdf_file in file_batch
                }

                # Process completed tasks
                batch_data = []
                for future in as_completed(future_to_file):
                    pdf_file = future_to_file[future]
                    filename = os.path.basename(str(pdf_file))

                    try:
                        data, date_str, metadata = future.result(timeout=180)  # 3 minute timeout

                        if metadata['success']:
                            if data:
                                batch_data.append(data)
                                if date_str:
                                    date_file_map[date_str] = filename
                            self.processed_count += 1
                            print(f"✓ {filename} - {metadata['rows_extracted']} rows")
                        else:
                            self.failed_count += 1
                            print(f"✗ {filename} - {metadata['error']}")

                    except TimeoutError:
                        self.failed_count += 1
                        print(f"⏰ Timeout: {filename}")
                    except Exception as e:
                        self.failed_count += 1
                        print(f"✗ Error: {filename} - {e}")

                # Add batch data to main collection
                for data_chunk in batch_data:
                    all_data.append(data_chunk)

                # Clear batch data to free memory
                del batch_data
                gc.collect()

        # Print summary
        print(f"\nProcessing Summary:")
        print(f"  Successful: {self.processed_count}")
        print(f"  Failed: {self.failed_count}")

        return all_data, date_file_map

    def analyze_data_structure(self, all_data: List[List[List[str]]]) -> int:
        """Analyze data structure efficiently using sampling"""
        if not all_data:
            return 7  # Default column count

        # Use sampling for large datasets
        total_rows = sum(len(chunk) for chunk in all_data)
        sample_size = min(500, total_rows)

        if total_rows <= sample_size:
            # Process all data if small
            column_counts = defaultdict(int)
            for data_chunk in all_data:
                for row in data_chunk:
                    column_counts[len(row)] += 1
        else:
            # Sample data for analysis
            column_counts = defaultdict(int)
            sampled = 0
            for data_chunk in all_data:
                for row in data_chunk:
                    column_counts[len(row)] += 1
                    sampled += 1
                    if sampled >= sample_size:
                        break
                if sampled >= sample_size:
                    break

        # Find optimal column count (most common + buffer)
        if column_counts:
            most_common = max(column_counts.items(), key=lambda x: x[1])[0]
            max_columns = max(column_counts.keys())
            # Use most common, but ensure we can handle larger rows
            return max(most_common, min(max_columns, most_common + 2))

        return 7

    def normalize_rows(self, data: List[List[str]], target_columns: int) -> List[List[str]]:
        """Normalize rows with efficient batch processing"""
        if not data:
            return []

        normalized = []

        for row in data:
            row_len = len(row)

            if row_len < target_columns:
                # Pad with empty strings
                normalized_row = row + [''] * (target_columns - row_len)
            elif row_len > target_columns:
                # Truncate to target columns
                normalized_row = row[:target_columns]
            else:
                normalized_row = row

            # Ensure all values are strings
            normalized_row = [
                '' if item is None or (isinstance(item, float) and pd.isna(item)) 
                else str(item).strip() 
                for item in normalized_row
            ]

            normalized.append(normalized_row)

        return normalized

    def sort_by_date(self, data: List[List[str]]) -> List[List[str]]:
        """Sort data by date (first column) from oldest to newest"""
        if not data:
            return data

        def date_key(row):
            date_str = row[0] if row else ''
            if date_str and re.match(r'\d{4}-\d{2}-\d{2}', date_str):
                try:
                    return datetime.strptime(date_str, '%Y-%m-%d')
                except ValueError:
                    return datetime.max
            return datetime.max

        return sorted(data, key=date_key)

    def process_folder_to_csv(self, folder_path: str, output_file: str = "combined_statements.csv") -> Optional[str]:
        """Main method to process folder of PDFs into sorted CSV"""
        try:
            folder_path = Path(folder_path)

            if not folder_path.exists():
                print(f"Error: Folder '{folder_path}' does not exist")
                return None

            # Get all PDF files (case-insensitive)
            pdf_files = []
            for ext in ['*.pdf', '*.PDF']:
                pdf_files.extend(folder_path.glob(ext))

            if not pdf_files:
                print(f"No PDF files found in {folder_path}")
                return None

            print(f"Found {len(pdf_files)} PDF files")

            # Reset counters
            self.processed_count = 0
            self.failed_count = 0
            self.total_pages = 0

            # Process PDFs in parallel with optimal resource usage
            all_data, _ = self.process_pdfs_parallel(pdf_files)

            if not all_data:
                print("No data extracted from PDFs")
                return None

            # Flatten data efficiently
            flattened_data = []
            for data_chunk in all_data:
                flattened_data.extend(data_chunk)

            if not flattened_data:
                print("No valid data to process")
                return None

            # Analyze and normalize data
            target_columns = self.analyze_data_structure(all_data)
            print(f"Using {target_columns} columns for output")

            normalized_data = self.normalize_rows(flattened_data, target_columns)

            # Sort by date (oldest to newest)
            sorted_data = self.sort_by_date(normalized_data)

            # Generate header
            base_headers = ['Statement Date', 'Posted Date', 'Value Date', 'Description', 
                          'Debit', 'Credit', 'Balance', 'Reference', 'Category']

            if target_columns > len(base_headers):
                additional_headers = [f'Extra_{i+1}' for i in range(len(base_headers), target_columns)]
                header = base_headers + additional_headers
            else:
                header = base_headers[:target_columns]

            # Write CSV in chunks to manage memory
            print(f"Writing sorted data to {output_file}...")

            # First pass: count rows for progress reporting
            total_rows = len(sorted_data)
            written_rows = 0

            with open(output_file, 'w', newline='', encoding='utf-8') as wFile:
                csv_writer = csv.writer(wFile)

                # Write header
                csv_writer.writerow(header)

                # Write data in chunks
                chunk_size = self.chunk_size
                for i in range(0, total_rows, chunk_size):
                    chunk = sorted_data[i:i + chunk_size]
                    csv_writer.writerows(chunk)
                    written_rows += len(chunk)
                    print(f"  Wrote {written_rows:,} of {total_rows:,} rows ({written_rows/total_rows:.1%})")

            print(f"\n✅ Successfully created {output_file}")
            print(f"📊 Total records: {total_rows:,}")

            # Show date range if available
            if total_rows > 0:
                first_date = sorted_data[0][0] if sorted_data[0] else ''
                last_date = sorted_data[-1][0] if sorted_data[-1] else ''

                if first_date and last_date:
                    print(f"📅 Date range: {first_date} to {last_date}")

            return output_file

        except Exception as e:
            print(f"Critical error: {str(e)}")
            print(traceback.format_exc())
            return None

if __name__ == "__main__":
    if len(sys.argv) < 2:
