```cpp
#include <vector>
#include <stdexcept>

using namespace std;

template<typename T>
vector<vector<T>> minor(const vector<vector<T>>& mat, size_t row, size_t col) {
    // Validate input
    if (mat.empty()) throw invalid_argument("Matrix cannot be empty");
    size_t n = mat.size();

    // Check if square
    for (const auto& r : mat) {
        if (r.size() != n) throw invalid_argument("Matrix must be square");
    }

    // Check indices
    if (row >= n || col >= n) {
        throw invalid_argument("Indices out of bounds");
    }

    // Special case for 1x1 matrix
    if (n == 1) return {};

    // Create minor matrix
    vector<vector<T>> minor_mat;
    for (size_t i = 0; i < n; ++i) {
        if (i == row) continue;
        vector<T> new_row;
        for (size_t j = 0; j < n; ++j) {
            if (j == col) continue;
            new_row.push_back(mat[i][j]);
        }
        minor_mat.push_back(new_row);
    }

    return minor_mat;
}

template<typename T>
T minor_determinant(const vector<vector<T>>& mat, size_t row, size_t col) {
    // Get minor matrix
    auto minor_mat = minor(mat, row, col);

    // Handle 1x1 minor case
    if (minor_mat.empty()) return 1;

    // Compute determinant of minor
    return determinant(minor_mat);
}

template<typename T>
T determinant(const vector<vector<T>>& mat) {
    size_t n = mat.size();

    // Base cases
    if (n == 1) return mat[0][0];
    if (n == 2) {
        return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
    }

    // Recursive case
    T det = 0;
    for (size_t j = 0; j < n; ++j) {
        // Create minor for element (0,j)
        vector<vector<T>> minor_mat;
        for (size_t i = 1; i < n; ++i) {
            vector<T> new_row;
            for (size_t k = 0; k < n; ++k) {
                if (k != j) new_row.push_back(mat[i][k]);
            }
            minor_mat.push_back(new_row);
        }

        // Compute cofactor
        T sign = (j % 2 == 0) ? 1 : -1;
        det += sign * mat[0][j] * determinant(minor_mat);
    }

    return det;
}
