def optimized_minor_determinant(matrix: List[List[float]], row: int, col: int, 
                               use_numpy: bool = True) -> float:
    """
    Optimized minor determinant calculation for larger matrices.

    Args:
        matrix: Square matrix as 2D list
        row: Row to remove (0-based)
        col: Column to remove (0-based)
        use_numpy: Use NumPy for large matrices (recommended)

    Returns:
        Determinant of the minor matrix

    Raises:
        ValueError: For invalid inputs
    """
    # Input validation
    if not matrix:
        raise ValueError("Matrix cannot be empty")

    n = len(matrix)

    # Check if square
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError(f"Matrix must be square. Row {i} has {len(matrix[i])} columns")

    # Check indices
    if row < 0 or row >= n or col < 0 or col >= n:
        raise ValueError(f"Indices out of bounds. Matrix is {n}x{n}")

    # Edge cases
    if n == 1:
        return 1.0  # Convention: determinant of empty matrix is 1

    if n == 2:
        # Direct calculation for 2x2
        return matrix[1-row][1-col]

    # For large matrices, use NumPy for efficiency
    if use_numpy and n > 4:
        A = np.array(matrix, dtype=float)

        # Create indices for rows/columns to keep
        rows_to_keep = [i for i in range(n) if i != row]
        cols_to_keep = [j for j in range(n) if j != col]

        # Extract submatrix efficiently using NumPy's advanced indexing
        minor_submatrix = A[np.ix_(rows_to_keep, cols_to_keep)]

        # Compute determinant using NumPy's optimized LAPACK routines
        return float(np.linalg.det(minor_submatrix))

    # For small matrices or when NumPy is not available
    # Create minor matrix efficiently using slicing
    minor_mat = []
    for i in range(n):
        if i == row:
            continue
        # Efficient slicing to skip the column
        minor_mat.append(matrix[i][:col] + matrix[i][col+1:])

    # Compute determinant recursively for small matrices
    return determinant_optimized_recursive(minor_mat)


