        psf = fspecial('gaussian', [5 5], 1.5);
    end

    % Estimate noise-to-signal ratio
    estimated_nsr = noise_variance / var(y(:));

    % Apply Wiener filter
    restored = deconvwnr(y, psf, estimated_nsr);
    restored = max(0, min(1, restored));  % Clip to valid range
end

% Lucy-Richardson Deconvolution
function restored = lucy_richardson_matlab(y, psf, iterations)
    % Convert to double
    y = im2double(y);

    % Default iterations
    if nargin < 3
        iterations = 20;
    end

    % If no PSF provided, create a basic one
    if nargin < 2 || isempty(psf)
        psf = fspecial('gaussian', [5 5], 1.5);
    end

    % Apply Lucy-Richardson deconvolution
    restored = deconvlucy(y, psf, iterations);
    restored = max(0, min(1, restored));  % Clip to valid range
end

% Demonstrate both methods on your degraded image
