    % Calculate and display metrics
    fprintf('\nRestoration Metrics:\n');
    fprintf('PSNR (Wiener): %.2f dB\n', psnr(restored_wiener, y));
    fprintf('PSNR (Lucy-Richardson): %.2f dB\n', psnr(restored_lr, y));
end
