```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <memory>
#include <random>
#include <cmath>
#include <stdexcept>
#include <algorithm>
#include <chrono>
#include <mutex>
#include <atomic>

// Forward declaration
class IzhikevichNeuron;

/**
 * @brief Connection structure between neurons
 * 
 * Stores synaptic weight and last spike time for STDP calculations
 */
struct Connection {
    std::shared_ptr<IzhikevichNeuron> target;
    double weight;
    double last_spike_time;

    Connection(std::shared_ptr<IzhikevichNeuron> t, double w) 
        : target(t), weight(w), last_spike_time(-1000.0) {}
};

/**
 * @brief Izhikevich neuron model implementation in C++
 * 
 * This class implements the Izhikevich neuron model with synaptic plasticity
 * and dynamic connectivity for large-scale network simulations.
 */
class IzhikevichNeuron {
private:
    // Neuron identification
    const size_t id_;

    // Izhikevich model parameters
    double a_;  // Time scale of recovery variable
    double b_;  // Sensitivity of recovery variable
    double c_;  // After-spike reset value of v
    double d_;  // After-spike reset of u
    double v_rest_;  // Resting membrane potential

    // State variables
    double v_;  // Membrane potential
    double u_;  // Recovery variable
    double I_;  // Input current

    // Spike tracking
    bool has_spiked_;
    std::vector<double> spike_times_;
    double last_spike_time_;

    // Connectivity
    std::unordered_map<size_t, std::shared_ptr<Connection>> input_connections_;
    std::unordered_map<size_t, std::shared_ptr<Connection>> output_connections_;

    // STDP parameters
    double stdp_learning_rate_;
    double stdp_tau_plus_;
    double stdp_tau_minus_;

    // Thread safety
    mutable std::mutex connections_mutex_;

    // Validation helpers
    void validate_weight(double weight) const {
        if (weight < 0.0 || weight > 1.0) {
            throw std::invalid_argument("Synaptic weight must be between 0.0 and 1.0");
        }
    }

    void validate_neuron_id(size_t neuron_id) const {
        if (neuron_id == id_) {
            throw std::invalid_argument("Cannot connect neuron to itself");
        }
    }

public:
    /**
     * @brief Construct a new Izhikevich Neuron object
     * 
     * @param id Unique neuron identifier
     * @param a Time scale of recovery variable (default: 0.02 for RS neurons)
     * @param b Sensitivity of recovery variable (default: 0.2)
     * @param c After-spike reset value of v (default: -65.0)
     * @param d After-spike reset of u (default: 8.0 for RS neurons)
     * @param v_rest Resting membrane potential (default: -70.0)
     */
    IzhikevichNeuron(size_t id, 
                     double a = 0.02, 
                     double b = 0.2, 
                     double c = -65.0, 
                     double d = 8.0, 
                     double v_rest = -70.0)
        : id_(id), a_(a), b_(b), c_(c), d_(d), v_rest_(v_rest),
          v_(v_rest), u_(b * v_rest), I_(0.0),
          has_spiked_(false), last_spike_time_(-1000.0),
          stdp_learning_rate_(0.01), stdp_tau_plus_(20.0), stdp_tau_minus_(20.0) {

        // Parameter validation
        if (a <= 0.0) throw std::invalid_argument("Parameter 'a' must be positive");
        if (b <= 0.0) throw std::invalid_argument("Parameter 'b' must be positive");
    }

    // Delete copy constructor and assignment operator
    IzhikevichNeuron(const IzhikevichNeuron&) = delete;
    IzhikevichNeuron& operator=(const IzhikevichNeuron&) = delete;

    // Allow move operations for performance
    IzhikevichNeuron(IzhikevichNeuron&&) = default;
    IzhikevichNeuron& operator=(IzhikevichNeuron&&) = default;

    /**
     * @brief Get neuron ID
     */
    size_t get_id() const { return id_; }

    /**
     * @brief Connect this neuron to a target neuron
     * 
     * @param target Target neuron to connect to
     * @param initial_weight Initial synaptic weight (0.0-1.0)
     * @return true Connection successful
     * @return false Connection failed
     */
    bool connect_to(std::shared_ptr<IzhikevichNeuron> target, double initial_weight = 0.5) {
        if (!target) {
            throw std::invalid_argument("Target neuron cannot be null");
        }

        validate_neuron_id(target->get_id());
        validate_weight(initial_weight);

        std::lock_guard<std::mutex> lock(connections_mutex_);

        size_t target_id = target->get_id();
        if (output_connections_.find(target_id) != output_connections_.end()) {
            return false;  // Connection already exists
        }

        // Create bidirectional connection
        auto connection = std::make_shared<Connection>(target, initial_weight);
        output_connections_[target_id] = connection;

        // Also add as input connection to target
        return target->receive_connection_from(shared_from_this(), initial_weight);
    }

    /**
     * @brief Accept a connection from a source neuron
     * 
     * @param source Source neuron connecting to this one
     * @param initial_weight Initial synaptic weight
     * @return true Connection successful
     * @return false Connection failed
     */
    bool receive_connection_from(std::shared_ptr<IzhikevichNeuron> source, double initial_weight) {
        if (!source) {
            throw std::invalid_argument("Source neuron cannot be null");
        }

        validate_neuron_id(source->get_id());
        validate_weight(initial_weight);

        std::lock_guard<std::mutex> lock(connections_mutex_);

        size_t source_id = source->get_id();
        if (input_connections_.find(source_id) != input_connections_.end()) {
            return false;  // Connection already exists
        }

        auto connection = std::make_shared<Connection>(source, initial_weight);
        input_connections_[source_id] = connection;
        return true;
    }

    /**
     * @brief Disconnect from a target neuron
     * 
     * @param target_id ID of target neuron to disconnect from
     * @return true Disconnection successful
     * @return false Disconnection failed
     */
    bool disconnect_from(size_t target_id) {
        std::lock_guard<std::mutex> lock(connections_mutex_);

        auto it = output_connections_.find(target_id);
        if (it != output_connections_.end()) {
            // Also remove from target's input connections
            if (auto target = it->second->target.lock()) {
                target->remove_connection_from(id_);
            }
            output_connections_.erase(it);
            return true;
        }
        return false;
    }

    /**
     * @brief Remove a connection from a source neuron
     * 
     * @param source_id ID of source neuron to remove
     * @return true Removal successful
     * @return false Removal failed
     */
    bool remove_connection_from(size_t source_id) {
        std::lock_guard<std::mutex> lock(connections_mutex_);
        return input_connections_.erase(source_id) > 0;
    }

    /**
     * @brief Calculate input current from spiking neurons
     * 
     * @param current_time Current simulation time
     * @return double Total input current
     */
    double calculate_input_current(double current_time) {
        double total_current = 0.0;

        std::lock_guard<std::mutex> lock(connections_mutex_);

        for (auto& [source_id, connection] : input_connections_) {
            if (auto source = connection->target.lock()) {
                if (source->has_spiked_) {
                    // Update last spike time for STDP
                    connection->last_spike_time = source->last_spike_time_;
                    total_current += connection->weight;
                }
            }
        }

        return total_current;
    }

    /**
     * @brief Update synaptic weights using STDP
     * 
     * @param current_time Current simulation time
     */
    void update_stdp(double current_time) {
        std::lock_guard<std::mutex> lock(connections_mutex_);

        if (has_spiked_) {
            // LTP: Pre-before-post spike timing
            for (auto& [source_id, connection] : input_connections_) {
                double delta_t = current_time - connection->last_spike_time;
                if (delta_t > 0 && connection->last_spike_time > -900.0) {
                    double weight_change = stdp_learning_rate_ * 
                                          std::exp(-delta_t / stdp_tau_plus_);
                    connection->weight = std::clamp(connection->weight + weight_change, 0.0, 1.0);
                }
            }
        }

        // LTD: Post-before-pre spike timing
        for (auto& [source_id, connection] : input_connections_) {
            double delta_t = current_time - last_spike_time_;
            if (delta_t > 0 && last_spike_time_ > -900.0 && 
                connection->last_spike_time > last_spike_time_) {
                double weight_change = -stdp_learning_rate_ * 
                                      std::exp(-delta_t / stdp_tau_minus_);
                connection->weight = std::clamp(connection->weight + weight_change, 0.0, 1.0);
            }
        }
    }

    /**
     * @brief Update neuron state for one time step
     * 
     * @param dt Time step size
     * @param current_time Current simulation time
     * @return true Neuron spiked
     * @return false Neuron did not spike
     */
    bool step(double dt, double current_time) {
        if (dt <= 0.0) {
            throw std::invalid_argument("Time step must be positive");
        }

        // Calculate input current
        I_ = calculate_input_current(current_time);

        // Izhikevich model equations
        double dv = (0.04 * v_ * v_ + 5.0 * v_ + 140.0 - u_ + I_) * dt;
        double du = (a_ * (b_ * v_ - u_)) * dt;

        v_ += dv;
        u_ += du;

        // Check for spike
        has_spiked_ = false;
        if (v_ >= 30.0) {  // Spike threshold
            has_spiked_ = true;
            spike_times_.push_back(current_time);
            last_spike_time_ = current_time;

            // Reset after spike
            v_ = c_;
            u_ += d_;
        }

        // Update synaptic weights using STDP
        update_stdp(current_time);

        return has_spiked_;
    }

    /**
     * @brief Get neuron state information
     */
    struct NeuronState {
        size_t id;
        double membrane_potential;
        double recovery_variable;
        bool has_spiked;
        size_t input_connections;
        size_t output_connections;
    };

    NeuronState get_state() const {
        std::lock_guard<std::mutex> lock(connections_mutex_);
        return {
            id_,
            v_,
            u_,
            has_spiked_,
            input_connections_.size(),
            output_connections_.size()
        };
    }

    /**
     * @brief Reset neuron to initial state
     */
    void reset() {
        v_ = v_rest_;
        u_ = b_ * v_rest_;
        I_ = 0.0;
        has_spiked_ = false;
        spike_times_.clear();
        last_spike_time_ = -1000.0;
    }

    /**
     * @brief Set STDP parameters
     */
    void set_stdp_params(double learning_rate, double tau_plus, double tau_minus) {
        if (learning_rate <= 0.0 || tau_plus <= 0.0 || tau_minus <= 0.0) {
            throw std::invalid_argument("STDP parameters must be positive");
        }
        stdp_learning_rate_ = learning_rate;
        stdp_tau_plus_ = tau_plus;
        stdp_tau_minus_ = tau_minus;
    }
};

/**
 * @brief Neural network for large-scale simulations
 * 
 * Manages a collection of Izhikevich neurons and provides
 * efficient network operations.
 */
class NeuralNetwork {
private:
    std::unordered_map<size_t, std::shared_ptr<IzhikevichNeuron>> neurons_;
    double current_time_;
    size_t next_neuron_id_;

    // Random number generation for connections
    std::mt19937 rng_;
    std::uniform_real_distribution<double> weight_dist_;

public:
    /**
     * @brief Construct a new Neural Network object
     * 
     * @param seed Random seed for connection generation
     */
    NeuralNetwork(unsigned int seed = std::chrono::system_clock::now().time_since_epoch().count())
        : current_time_(0.0), next_neuron_id_(0), rng_(seed), 
          weight_dist_(0.1, 0.9) {}

    /**
     * @brief Add a neuron to the network
     * 
     * @param neuron Neuron to add
     */
    void add_neuron(std::shared_ptr<IzhikevichNeuron> neuron) {
        if (!neuron) {
            throw std::invalid_argument("Neuron cannot be null");
        }

        size_t id = neuron->get_id();
        if (neurons_.find(id) != neurons_.end()) {
            throw std::runtime_error("Neuron with ID " + std::to_string(id) + " already exists");
        }

        neurons_[id] = neuron;
        next_neuron_id_ = std::max(next_neuron_id_, id + 1);
    }

    /**
     * @brief Create a new neuron and add it to the network
     * 
     * @param a Izhikevich parameter a
     * @param b Izhikevich parameter b
     * @param c Izhikevich parameter c
     * @param d Izhikevich parameter d
     * @return std::shared_ptr<IzhikevichNeuron> Created neuron
     */
    std::shared_ptr<IzhikevichNeuron> create_neuron(double a = 0.02, 
                                                    double b = 0.2, 
                                                    double c = -65.0, 
                                                    double d = 8.0) {
        auto neuron = std::make_shared<IzhikevichNeuron>(next_neuron_id_++, a, b, c, d);
        neurons_[neuron->get_id()] = neuron;
        return neuron;
    }

    /**
     * @brief Create random connections between neurons
     * 
     * @param connection_probability Probability of connection between any two neurons
     * @param allow_self_connections Whether to allow self-connections
     */
    void create_random_connections(double connection_probability = 0.1, 
                                   bool allow_self_connections = false) {
        if (connection_probability < 0.0 || connection_probability > 1.0) {
            throw std::invalid_argument("Connection probability must be between 0.0 and 1.0");
        }

        std::vector<size_t> neuron_ids;
        neuron_ids.reserve(neurons_.size());
        for (const auto& [id, neuron] : neurons_) {
            neuron_ids.push_back(id);
        }

        std::uniform_real_distribution<double> prob_dist(0.0, 1.0);

        for (size_t source_id : neuron_ids) {
            for (size_t target_id : neuron_ids) {
                if (!allow_self_connections && source_id == target_id) {
                    continue;
                }

                if (prob_dist(rng_) < connection_probability) {
                    double weight = weight_dist_(rng_);
                    auto source = neurons_[source_id];
                    auto target = neurons_[target_id];

                    try {
                        source->connect_to(target, weight);
                    } catch (const std::exception& e) {
                        // Log error but continue with other connections
                        std::cerr << "Warning: Failed to connect neuron " 
                                  << source_id << " to " << target_id 
                                  << ": " << e.what() << std::endl;
                    }
                }
            }
        }
    }

    /**
     * @brief Update all neurons in the network for one time step
     * 
     * @param dt Time step size
     */
    void step(double dt) {
        if (dt <= 0.0) {
            throw std::invalid_argument("Time step must be positive");
        }

        // Update each neuron
        for (auto& [id, neuron] : neurons_) {
            neuron->step(dt, current_time_);
        }

        current_time_ += dt;
    }

    /**
     * @brief Get network state information
     */
    struct NetworkState {
        double current_time;
        size_t total_neurons;
        size_t active_neurons;
        size_t total_connections;
        std::vector<IzhikevichNeuron::NeuronState> neuron_states;
    };

    NetworkState get_network_state() const {
        NetworkState state;
        state.current_time = current_time_;
        state.total_neurons = neurons_.size();
        state.active_neurons = 0;
        state.total_connections = 0;

        state.neuron_states.reserve(neurons_.size());
        for (const auto& [id, neuron] : neurons_) {
            auto neuron_state = neuron->get_state();
            state.neuron_states.push_back(neuron_state);

            if (neuron_state.has_spiked) {
                state.active_neurons++;
            }
            state.total_connections += neuron_state.input_connections;
        }

        return state;
    }
};

