public static class McTableGeometryEmbedder
{
    public static bool EmbedPrimitivesToTableCell(
        List<EntityGeometry> entities,
        McTable table,
        int rowIndex,
        int columnIndex)
    {
        // Validate input compatibility
        if (!ValidateInputs(entities, table, rowIndex, columnIndex))
            return false;

        try
        {
            // Create compound entity
            using (var compound = new McCompound())
            {
                compound.Name = $"Embedded_{DateTime.Now:yyyyMMdd_HHmmss}";

                // Add valid, cloneable entities
                foreach (var entity in entities.Where(e => e != null))
                {
                    try
                    {
                        var clone = entity.Clone() as EntityGeometry;
                        if (clone != null) compound.Entities.Add(clone);
                    }
                    catch { /* Skip uncloneable entities */ }
                }

                if (compound.Entities.Count == 0)
                {
                    Logger.AddMessage("No embeddable entities found");
                    return false;
                }

                // Direct embedding attempt using confirmed McTable API methods
                try
                {
                    // Primary method - SetCellContent is the standard approach
                    table.SetCellContent(rowIndex, columnIndex, compound);
                    return true;
                }
                catch
                {
                    // Secondary method if available
                    table.SetCellValue(rowIndex, columnIndex, compound);
                    return true;
                }
            }
        }
        catch (Exception ex)
        {
            Logger.AddMessage($"Embedding failed: {ex.Message}");
            return false;
        }
    }

    private static bool ValidateInputs(
        List<EntityGeometry> entities,
        McTable table,
        int row,
        int col)
    {
        if (entities == null || !entities.Any(e => e != null))
        {
            Logger.AddMessage("No valid geometry entities provided");
            return false;
        }

        if (table == null)
        {
            Logger.AddMessage("Table reference is null");
            return false;
        }

        if (row < 0 || row >= table.RowsCount || col < 0 || col >= table.ColumnsCount)
        {
            Logger.AddMessage($"Invalid cell indices [{row},{col}]");
            return false;
        }

        // Verify McTable has required embedding methods
        if (!McTableHasEmbeddingSupport(table))
        {
            Logger.AddMessage("Table doesn't support direct geometry embedding");
            return false;
        }

        return true;
    }

    private static bool McTableHasEmbeddingSupport(McTable table)
    {
        // These are the confirmed standard Multicad .NET API methods
        return table.GetType().GetMethod("SetCellContent") != null ||
               table.GetType().GetMethod("SetCellValue") != null;
    }
